/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    function normaliseDateFilter(dateFilter, defaultValue) {
        if (dateFilter && dateFilter.start == dateFilter.end) {
            const today = new Date();
            let todayDate = today.getFullYear() + "-" + (today.getMonth() + 1) + "-" + today.getDate();
            if (todayDate == dateFilter.start) {
                dateFilter.start = defaultValue.start;
                dateFilter.end = defaultValue.end;
                dateFilter.dynamicTimeRange = defaultValue.dynamicTimeRange;

                return dateFilter;
            }
        }
        return dateFilter;
    };
    const dateFilter = event.payload.appliedFilters.find(function(f) {
        return f.type == 'date';
    });
    normaliseDateFilter(dateFilter, api.state.defaultDateFilter);
    const params = {

    };
    if (dateFilter) {
        params.startDate = dateFilter.start;
        params.endDate = dateFilter.end;
        params.dynamicTimeRange = dateFilter.dynamicTimeRange;
    }
    return {
        params
    };
}

